{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-open-design-landing-deck",
  "title": "Write a Brand-Story Deck like a Founder Storyteller",
  "title_i18n": {
    "en": "Write a Brand-Story Deck like a Founder Storyteller",
    "zh-CN": "像会讲故事的创始人一样写品牌故事稿",
    "zh-TW": "像会讲故事的创始人一样写品牌故事稿"
  },
  "version": "0.1.0",
  "publishedAt": "2026-05-12T07:18:16Z",
  "description": "Open Design's brand-story deck for partners and press: why it exists, what it believes, and where design is going. Built as a decision-grade marketing & GTM deck for partners, press, community.",
  "description_i18n": {
    "en": "Open Design's brand-story deck for partners and press: why it exists, what it believes, and where design is going. Built as a decision-grade marketing & GTM deck for partners, press, community.",
    "zh-CN": "像会讲故事的创始人一样写品牌故事稿——一份可商业交付的市场增长 Deck，围绕真实主题、证据链与决策目标组织。",
    "zh-TW": "像会讲故事的创始人一样写品牌故事稿——一份可商业交付的市场增长 Deck，围绕真实主题、证据链与决策目标组织。"
  },
  "license": "MIT",
  "author": {
    "name": "Open Design",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/examples/open-design-landing-deck",
  "tags": [
    "example",
    "first-party",
    "deck",
    "marketing",
    "web",
    "slide-deck",
    "untitled",
    "pitch-deck",
    "keynote",
    "editorial-slides",
    "atelier-zero-deck",
    "open-design-deck",
    "open-design-landing-deck",
    "consulting-deliverable",
    "strategy",
    "client",
    "consulting-delivery",
    "marketing-gtm",
    "annual-marketing-plan",
    "launch",
    "campaign",
    "pipeline",
    "decision-deck",
    "commercial-slide-agent"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "deck",
    "scenario": "marketing",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html"
    },
    "useCase": {
      "query": {
        "en": "Create \"Write a Brand-Story Deck like a Founder Storyteller\" as a decision-grade Marketing & GTM deck in this template's own visual system. Subject: Open Design's brand-story deck for partners and press: why it exists, what it believes, and where design is going. Audience: partners, press, community. First ask only for missing essentials: audience, decision target, source-of-truth materials, deadline, and must-keep numbers. Then produce the slide plan, written slides, visual direction, speaker-ready structure, and a critic pass against this rubric: can the plan connect creative choices to measurable growth.",
        "zh-CN": "像会讲故事的创始人一样写品牌故事稿。像会讲故事的创始人一样写品牌故事稿——一份可商业交付的市场增长 Deck，围绕真实主题、证据链与决策目标组织。 主题：Open Design's brand-story deck for partners and press: why it exists, what it believes, and where design is going. 先确认受众、决策目标、素材来源、截止时间和必须保留的数据，再输出叙事主线、页面规划、逐页文案、视觉方向和按评审标准自检的版本。"
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Write a Brand-Story Deck like a Founder Storyteller",
          "title_i18n": {
            "en": "Write a Brand-Story Deck like a Founder Storyteller",
            "zh-CN": "像会讲故事的创始人一样写品牌故事稿",
            "zh-TW": "像会讲故事的创始人一样写品牌故事稿"
          }
        }
      ]
    },
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "designSystem": {
        "primary": true
      },
      "craft": [
        "typographic-rhythm",
        "pixel-discipline"
      ],
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ],
    "category": "marketing-gtm"
  }
}
